def get_bg_val(grid):
    return max(set(grid[0]).union(*grid), key=lambda x: sum(row.count(x) for row in grid))

def fill_GOC2(grid):
    bg = get_bg_val(grid)
    result = [list(row) for row in grid]

    for row_idx, row in enumerate(result):
        non_bg_cols = [c for c in range(len(row)) if row[c] != bg]

        if len(non_bg_cols) >= 2:
            for c in range(non_bg_cols[0] + 1, non_bg_cols[-1]):
                if result[row_idx][c] == bg:
                    result[row_idx][c] = 2
        elif len(non_bg_cols) == 1:
            col = non_bg_cols[0]
            nb = row[col]

            # offset depends on nb_value
            # nb=0: offset = 3 - col
            # nb=3: offset = 2 - col
            offset = (3 - nb // 3) - col

            dist = nb + offset

            for ff in range(dist):
                if col + 1 + ff < len(result[row_idx]) and result[row_idx][col + 1 + ff] == bg:
                    result[row_idx][col + 1 + ff] = 2

    return result

